import { app, BrowserWindow, dialog, session, shell, type WebContents } from "electron";
import { appendFileSync } from "node:fs";
import path from "node:path";
import { trustBankCertificate } from "./certificate";
import { isAppUrl, isBankConsent, isExternalAllowed } from "./navigation";
import { log, readSettings, updateSettings } from "./paths";

export const devToolsAllowed = () => !app.isPackaged || process.env.MONEO_DESKTOP_DEBUG === "1";
export const iconPath = () => path.join(__dirname, "..", "icons", "icon.png");

let appPort = 0;
let reloadOnFocus = false;

/** Opens an address in the system browser. Tests log it to a file instead. */
export async function openExternal(url: string) {
  if (!isExternalAllowed(url, appPort)) { log(`Blocked opening ${new URL(url).protocol} address`); return; }
  if (isBankConsent(url) && !readSettings().bankCertificateTrusted) await offerBankTrust();
  const testLog = process.env.MONEO_DESKTOP_OPEN_EXTERNAL_LOG;
  if (testLog) appendFileSync(testLog, `${url}\n`);
  else await shell.openExternal(url);
}

// The bank sends the owner back to https://localhost:3443; without this the browser warns there.
async function offerBankTrust() {
  if (process.env.MONEO_DESKTOP_OPEN_EXTERNAL_LOG) return;
  const { response } = await dialog.showMessageBox({
    type: "info", buttons: ["Continue", "Skip"], defaultId: 0, cancelId: 1, title: "Connect your bank",
    message: "Allow your bank to send you back to Moneo",
    detail: "After you approve access at your bank, it returns you to Moneo through a secure address on this computer. "
      + "Moneo made a certificate for that address that only this computer uses. Your computer will now ask once whether to trust it.",
  });
  if (response === 0 && await trustBankCertificate()) updateSettings({ bankCertificateTrusted: true });
}

/** Allows only the microphone (voice calls) and copying, and only for Moneo's own pages. */
export function lockDownSession() {
  const ours = (url: string | undefined) => Boolean(url && isAppUrl(url, appPort));
  session.defaultSession.setPermissionRequestHandler((_contents, permission, callback, details) => {
    const audioOnly = permission === "media" && "mediaTypes" in details && (details.mediaTypes ?? []).every(type => type === "audio");
    callback(ours(details.requestingUrl) && (audioOnly || permission === "clipboard-sanitized-write"));
  });
  session.defaultSession.setPermissionCheckHandler((_contents, permission, origin) =>
    ours(origin) && (permission === "media" || permission === "clipboard-sanitized-write"));
  app.on("web-contents-created", (_event, contents) => {
    contents.setWindowOpenHandler(({ url }) => { void openExternal(url); return { action: "deny" }; });
    contents.on("will-attach-webview", event => event.preventDefault());
  });
}

function guardNavigation(contents: WebContents) {
  const leave = (event: Electron.Event, url: string) => {
    if (isAppUrl(url, appPort)) return;
    event.preventDefault();
    // Sign-ins (ChatGPT, banks, Scalable) run in the system browser and come back to Moneo's loopback callbacks.
    reloadOnFocus = true;
    void openExternal(url);
  };
  contents.on("will-navigate", event => leave(event, event.url));
  contents.on("will-redirect", event => { if (event.isMainFrame) leave(event, event.url); });
}

export function createAppWindow(port: number, hooks: { onClose(event: Electron.Event): void }) {
  appPort = port;
  const window = new BrowserWindow({
    width: 1280, height: 860, minWidth: 380, minHeight: 500, show: false, title: "Moneo", icon: iconPath(),
    backgroundColor: "#0f1011", autoHideMenuBar: true,
    webPreferences: { contextIsolation: true, sandbox: true, nodeIntegration: false, webSecurity: true, devTools: devToolsAllowed(), spellcheck: false },
  });
  guardNavigation(window.webContents);
  window.on("close", hooks.onClose);
  // Back from a sign-in in the browser: show what it changed.
  window.on("focus", () => {
    if (!reloadOnFocus) return;
    reloadOnFocus = false;
    window.webContents.reload();
  });
  return window;
}

export const setAppPort = (port: number) => { appPort = port; };

import { app, Menu, nativeImage, Tray } from "electron";
import { iconPath } from "./app-window";

export type TrayActions = {
  open(): void;
  openInBrowser(): void;
  backUp(): void;
  openBackups(): void;
  restore(): void;
  quit(): void;
};

let tray: Tray | undefined;

// Login start is per user. Windows and Linux pass --hidden; macOS reports wasOpenedAtLogin instead.
export const startsAtLogin = () => app.getLoginItemSettings({ args: ["--hidden"] }).openAtLogin;
export const openedAtLogin = () => process.argv.includes("--hidden") || app.getLoginItemSettings().wasOpenedAtLogin === true;

export function createTray(actions: TrayActions) {
  const size = process.platform === "darwin" ? 18 : 16;
  tray = new Tray(nativeImage.createFromPath(iconPath()).resize({ width: size, height: size }));
  tray.setToolTip("Moneo");
  const build = () => Menu.buildFromTemplate([
    { label: "Open Moneo", click: actions.open },
    { label: "Open in browser", click: actions.openInBrowser },
    { type: "separator" },
    { label: "Back up now", click: actions.backUp },
    { label: "Open backups folder", click: actions.openBackups },
    { label: "Restore from backup…", click: actions.restore },
    { type: "separator" },
    {
      label: "Start Moneo when I sign in", type: "checkbox", checked: startsAtLogin(),
      click: item => {
        app.setLoginItemSettings({ openAtLogin: item.checked, args: ["--hidden"] });
        tray?.setContextMenu(build());
      },
    },
    { type: "separator" },
    { label: "Quit Moneo", click: actions.quit },
  ]);
  tray.setContextMenu(build());
  // Windows and Linux: a click on the icon opens the window; the menu is on right-click.
  if (process.platform !== "darwin") tray.on("click", actions.open);
  return tray;
}

import { app, BrowserWindow, dialog, Notification, powerMonitor, shell } from "electron";
import { existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import { backup, restore, startBackend, type BackendPaths, type RunningBackend } from "#backend";
import { createAppWindow, lockDownSession, openExternal, setAppPort } from "./app-window";
import { ensureBankCertificate } from "./certificate";
import { NextServer } from "./next-server";
import { backupsDir, home, log, readSettings, resources, setupHome, updateSettings } from "./paths";
import { choosePort } from "./port";
import { closeSetup, focusSetup, progress, registerSetupIpc, setSetupState, showSetup } from "./setup-window";
import { createTray, openedAtLogin } from "./tray";

setupHome();
if (!app.requestSingleInstanceLock()) app.quit();
else main();

function main() {
  const paths: BackendPaths = { resources: resources(), home: home() };
  const hidden = openedAtLogin();
  let backend: RunningBackend | undefined;
  let server: NextServer | undefined;
  let window: BrowserWindow | undefined;
  let booting: Promise<void> | undefined;
  let busy = false; // stopping for a restore or a retry: service exits are expected
  let quitting = false;
  let backupTimer: NodeJS.Timeout | undefined;

  const message = (error: unknown) => error instanceof Error ? error.message : String(error);

  function fail(summary: string, error: unknown) {
    log(`${summary}: ${message(error)}`);
    const [first, ...rest] = message(error).split("\n");
    setSetupState({ phase: "failed", error: { summary: `${summary}: ${first}`, detail: rest.join("\n") } });
    focusSetup();
  }

  async function stopServices() {
    clearInterval(backupTimer);
    await server?.stop().catch(error => log(`Stopping the server failed: ${message(error)}`));
    server = undefined;
    await backend?.stop().catch(error => log(`Stopping the backend failed: ${message(error)}`));
    backend = undefined;
  }

  function boot() {
    booting ??= (async () => {
      setSetupState({ phase: "starting", steps: [], error: undefined, firstRun: !existsSync(path.join(paths.home, "config.json")) });
      if (!hidden || window) showSetup(!window?.isVisible());
      try {
        const port = await choosePort();
        setAppPort(port);
        progress({ id: "certificate", label: "Preparing bank connections", state: "running" });
        const certificate = await ensureBankCertificate();
        progress({ id: "certificate", label: "Preparing bank connections", state: "done", detail: certificate ? undefined : "Unavailable; see the logs" });
        const running = await startBackend(paths, progress);
        backend = running;
        running.onExit((service, code) => {
          if (quitting || busy || backend !== running) return;
          fail(`A Moneo service stopped (${service})`, new Error(`It exited with code ${code}. Try again, or open the logs folder.`));
        });
        progress({ id: "app", label: "Starting Moneo", state: "running" });
        server = new NextServer({ appDir: path.join(paths.resources, "app"), port, env: running.env }, error => fail("The Moneo server keeps stopping", error));
        await server.start();
        progress({ id: "app", label: "Starting Moneo", state: "done" });
        await showApp(port, !hidden || Boolean(window?.isVisible()));
        closeSetup();
        scheduleBackups();
      } catch (error) {
        progress({ id: "app", label: "Starting Moneo", state: "error" });
        await stopServices();
        fail("Moneo could not start", error);
      }
    })().finally(() => { booting = undefined; });
    return booting;
  }

  async function showApp(port: number, visible: boolean) {
    window ??= createAppWindow(port, {
      onClose: event => {
        if (quitting) return;
        // Closing keeps Moneo running in the tray: background jobs and phone access keep working.
        event.preventDefault();
        window?.hide();
        if (!readSettings().trayNoticeShown && Notification.isSupported()) {
          new Notification({ title: "Moneo is still running", body: "Background syncs and phone access keep working. Open Moneo or quit it from its icon in the tray." }).show();
          updateSettings({ trayNoticeShown: true });
        }
      },
    });
    // Windows ends the session through the window; finish cleanly within the time it gives.
    window.on("session-end", () => { void quit(); });
    await window.loadURL(`http://localhost:${port}/`);
    if (visible) window.show();
  }

  function openWindow() {
    if (window && !booting) {
      if (window.isMinimized()) window.restore();
      window.show();
      window.focus();
    } else focusSetup();
  }

  // Backups: one a day while Moneo runs, checked hourly so a sleeping computer catches up.
  function scheduleBackups() {
    const check = async () => {
      const last = Date.parse(readSettings().lastBackupAt ?? "");
      if (Number.isFinite(last) && Date.now() - last < 24 * 3_600_000) return;
      await backUp("daily", false);
    };
    clearInterval(backupTimer);
    backupTimer = setInterval(check, 3_600_000);
    void check();
  }

  async function backUp(reason: string, notify: boolean) {
    if (!backend) return null;
    try {
      const folder = await backup(paths, reason);
      updateSettings({ lastBackupAt: new Date().toISOString() });
      log(`Backup (${reason}) written to ${folder}`);
      if (notify && Notification.isSupported()) new Notification({ title: "Moneo backed up", body: folder }).show();
      return folder;
    } catch (error) {
      log(`Backup (${reason}) failed: ${message(error)}`);
      if (notify) dialog.showErrorBox("Backup failed", message(error));
      return null;
    }
  }

  async function restoreBackup() {
    mkdirSync(backupsDir(), { recursive: true });
    const picked = await dialog.showOpenDialog({ title: "Restore Moneo from a backup", defaultPath: backupsDir(), properties: ["openDirectory"] });
    const folder = picked.filePaths[0];
    if (picked.canceled || !folder) return;
    const { response } = await dialog.showMessageBox({
      type: "warning", buttons: ["Restore", "Cancel"], defaultId: 1, cancelId: 1, title: "Restore from backup",
      message: `Restore Moneo from ${path.basename(folder)}?`,
      detail: "Your current data is replaced by this backup. Moneo backs up the current data first (when it is running), so you can go back.",
    });
    if (response !== 0) return;
    busy = true;
    try {
      await booting;
      await backUp("before-restore", false);
      setSetupState({ phase: "restoring", steps: [], error: undefined });
      window?.hide();
      focusSetup();
      await stopServices();
      await restore(paths, folder);
      log(`Restored from ${folder}`);
    } catch (error) {
      busy = false;
      fail("Restoring the backup failed", error);
      return;
    }
    busy = false;
    await boot();
  }

  async function retry() {
    busy = true;
    await stopServices();
    busy = false;
    await boot();
  }

  // Explicit quit: stop the server, then the database, then exit. Forced after 20 seconds.
  let quitPromise: Promise<void> | undefined;
  function quit() {
    quitPromise ??= (async () => {
      quitting = true;
      log("Quitting");
      const notice = setTimeout(() => { setSetupState({ phase: "stopping", steps: [], error: undefined }); focusSetup(); }, 1_500);
      const force = setTimeout(() => { log("Shutdown took too long; exiting"); app.exit(0); }, 20_000);
      await booting?.catch(() => {});
      await stopServices();
      clearTimeout(notice);
      clearTimeout(force);
      log("Stopped");
      app.exit(0);
    })();
    return quitPromise;
  }

  app.on("second-instance", (_event, argv) => {
    if (argv.includes("--quit")) void quit();
    else openWindow();
  });
  app.on("before-quit", event => { event.preventDefault(); void quit(); });
  app.on("window-all-closed", () => { /* keep running in the tray */ });
  app.on("activate", openWindow);

  app.whenReady().then(() => {
    log(`Moneo ${app.getVersion()} starting (home ${paths.home})`);
    lockDownSession();
    registerSetupIpc({ retry: () => void retry(), restore: restoreBackup, quit: () => void quit() });
    createTray({
      open: openWindow,
      openInBrowser: () => { const port = readSettings().port; if (port) void openExternal(`http://localhost:${port}/`); },
      backUp: () => void backUp("manual", true),
      openBackups: () => { mkdirSync(backupsDir(), { recursive: true }); void shell.openPath(backupsDir()); },
      restore: () => void restoreBackup(),
      quit: () => void quit(),
    });
    // macOS and Linux announce shutdown here; delaying lets the database close cleanly.
    powerMonitor.on("shutdown", event => { event.preventDefault(); void quit(); });
    void boot();
  });
}

