// Shared helpers for the packaged-app checks (package-smoke.mjs, package-journey.mjs, package-upgrade.mjs).
// Every run uses temporary Moneo homes, logs external links instead of opening a browser, and only
// ever stops processes it started itself.
import { execFileSync, spawn } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createServer } from "node:net";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";

export const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const release = path.join(root, "desktop", "release");

export function defaultExe() {
  return {
    win32: path.join(release, "win-unpacked", "Moneo.exe"),
    darwin: path.join(release, process.arch === "arm64" ? "mac-arm64" : "mac", "Moneo.app", "Contents", "MacOS", "Moneo"),
    linux: path.join(release, "linux-unpacked", "moneo"),
  }[process.platform];
}

export const results = [];
export function check(name, ok, detail = "") {
  results.push({ name, ok: Boolean(ok), detail });
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? ` — ${detail}` : ""}`);
  return Boolean(ok);
}
export function summary() {
  const failed = results.filter(result => !result.ok).length;
  console.log(failed ? `${failed} check(s) failed` : `All ${results.length} checks passed`);
  return failed;
}

export async function until(what, test, timeout) {
  const deadline = Date.now() + timeout;
  for (;;) {
    const value = await test().catch(() => undefined);
    if (value) return value;
    if (Date.now() > deadline) throw new Error(`Timed out waiting for ${what}`);
    await new Promise(resolve => setTimeout(resolve, 250));
  }
}

export const freePort = () => new Promise(resolve => { const server = createServer().listen(0, "127.0.0.1", () => { const { port } = server.address(); server.close(() => resolve(port)); }); });
export const alive = pid => { try { process.kill(pid, 0); return true; } catch { return false; } };

const user32 = `Add-Type -Namespace W -Name U -MemberDefinition '[DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, uint m, IntPtr w, IntPtr l); [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);'`;
export const powershell = command => execFileSync("powershell.exe", ["-NoProfile", "-Command", command], { encoding: "utf8", maxBuffer: 64 << 20 }).trim();
const win32 = command => powershell(`${user32}; ${command}`);

/** Process table: pid, parent, name, command line. */
function processTable() {
  if (process.platform === "win32") {
    return JSON.parse(powershell("Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,Name,CommandLine | ConvertTo-Json -Compress"))
      .map(row => ({ pid: row.ProcessId, ppid: row.ParentProcessId, name: row.Name, command: row.CommandLine ?? "" }));
  }
  return execFileSync("ps", ["-axo", "pid=,ppid=,command="], { encoding: "utf8" }).trim().split("\n").map(line => {
    const [, pid, ppid, command] = line.match(/^\s*(\d+)\s+(\d+)\s+(.*)$/);
    return { pid: Number(pid), ppid: Number(ppid), name: path.basename(command.split(" ")[0]), command };
  });
}

/** Every process started from the app, or naming its home folder (pg_ctl's postgres outlives its parent). */
export function processesOf(mainPid, home) {
  const rows = processTable();
  const found = new Map(rows.filter(row => row.pid === mainPid || row.command.toLowerCase().includes(home.toLowerCase())).map(row => [row.pid, row]));
  for (let grew = true; grew;) {
    grew = false;
    for (const row of rows) if (found.has(row.ppid) && !found.has(row.pid)) { found.set(row.pid, row); grew = true; }
  }
  return [...found.values()];
}

export function listeningPid(port) {
  if (process.platform !== "win32") return Number(execFileSync("lsof", ["-ti", `tcp:${port}`, "-sTCP:LISTEN"], { encoding: "utf8" }).trim().split("\n")[0]) || null;
  return Number(powershell(`(Get-NetTCPConnection -State Listen -LocalPort ${port} -ErrorAction SilentlyContinue | Select-Object -First 1).OwningProcess`)) || null;
}

export function tempHome(label) {
  return mkdtempSync(path.join(os.tmpdir(), `moneo-desktop-${label}-`));
}

/** A Moneo home plus the processes launched in it. */
export class Desktop {
  constructor(exe, label, extraEnv = {}) {
    this.exe = exe;
    this.home = tempHome(label);
    this.externalLog = path.join(os.tmpdir(), `moneo-desktop-${label}-${process.pid}-external.log`);
    writeFileSync(this.externalLog, "");
    this.env = { ...process.env, MONEO_DESKTOP_HOME: this.home, MONEO_DESKTOP_OPEN_EXTERNAL_LOG: this.externalLog, MONEO_DESKTOP_DEBUG: "1", ...extraEnv };
    this.seen = new Map();
  }

  /** Starts the app with a DevTools port (allowed only with MONEO_DESKTOP_DEBUG=1). */
  async launch(args = []) {
    this.cdpPort = await freePort();
    const child = spawn(this.exe, [`--remote-debugging-port=${this.cdpPort}`, "--use-fake-device-for-media-stream", ...args], { env: this.env, stdio: "ignore" });
    this.child = child;
    child.exited = false;
    child.on("exit", code => { child.exited = true; child.code = code; });
    await until("the DevTools endpoint", () => this.targets(), 30_000);
    return child;
  }

  async targets() {
    return (await (await fetch(`http://127.0.0.1:${this.cdpPort}/json/list`)).json());
  }
  async urls() { return (await this.targets()).map(target => target.url); }

  async browser() {
    this.cdp ??= await chromium.connectOverCDP(`http://127.0.0.1:${this.cdpPort}`);
    return this.cdp;
  }

  async page(match, timeout = 240_000) {
    await until(`a window at ${match}`, async () => (await this.urls()).some(url => match.test(url)), timeout);
    const browser = await this.browser();
    return until("its page", async () => browser.contexts().flatMap(context => context.pages()).find(page => match.test(page.url())), 15_000);
  }

  appPage(timeout) { return this.page(/^http:\/\/localhost:\d+\//, timeout); }
  setupPage(timeout = 30_000) { return this.page(/\/setup\/index\.html$/, timeout); }

  /** Remembers this launch's processes so the checks (and cleanup) can account for them. */
  snapshot() {
    for (const row of processesOf(this.child.pid, this.home)) this.seen.set(row.pid, row);
    return [...this.seen.values()];
  }

  /** A second launch: forwards its arguments to the running app, then exits. */
  async second(args) {
    const child = spawn(this.exe, args, { env: this.env, stdio: "ignore" });
    await new Promise(resolve => child.on("exit", resolve));
  }

  async quit() {
    await this.cdp?.close().catch(() => {});
    this.cdp = undefined;
    await this.second(["--quit"]);
    await until("Moneo to exit", async () => this.child.exited, 60_000);
  }

  log(name = "main.log") {
    const file = path.join(this.home, "logs", name);
    return existsSync(file) ? readFileSync(file, "utf8") : "";
  }
  external() { return readFileSync(this.externalLog, "utf8"); }
  settings() { return JSON.parse(readFileSync(path.join(this.home, "shell.json"), "utf8")); }

  mainWindow() {
    return win32(`(Get-Process -Id ${this.child.pid}).MainWindowHandle`);
  }
  /** Windows: the message the title bar's close button sends. */
  closeWindow(handle) { win32(`[W.U]::PostMessage([IntPtr]${handle}, 0x10, [IntPtr]::Zero, [IntPtr]::Zero)`); }
  windowVisible(handle) { return win32(`[W.U]::IsWindowVisible([IntPtr]${handle})`) === "True"; }

  async cleanup({ keepHome = false } = {}) {
    await this.cdp?.close().catch(() => {});
    if (this.child && !this.child.exited) await this.quit().catch(() => {});
    // Only processes these launches started.
    for (const row of this.snapshotSafe()) if (alive(row.pid)) try { process.kill(row.pid); } catch { /* gone */ }
    if (results.some(result => !result.ok)) {
      for (const name of ["main.log", "next.log"]) {
        const text = this.log(name);
        if (text) console.log(`--- ${name} (${this.home}) ---\n${text.slice(-3000)}`);
      }
    }
    if (!keepHome) rmSync(this.home, { recursive: true, force: true, maxRetries: 10, retryDelay: 500 });
    rmSync(this.externalLog, { force: true });
  }

  snapshotSafe() {
    try { if (this.child) this.snapshot(); } catch { /* process table unavailable */ }
    return [...this.seen.values()];
  }
}

/** Imports a CSV through the app's own API, as the import page does once the columns are chosen, and waits for it. */
export async function importCsv(page, { filename, csv, accountName }) {
  const mapping = { accountName, currencyCode: "EUR", dateColumn: "date", descriptionColumn: "description", amountColumn: "amount", dateFormat: "iso", amountSign: "signed", numericConvention: "decimal-dot" };
  const response = await page.request.post("/api/imports/confirm", { multipart: { file: { name: filename, mimeType: "text/csv", buffer: Buffer.from(csv) }, mapping: JSON.stringify(mapping) } });
  if (!response.ok()) throw new Error(`import ${filename}: ${response.status()} ${await response.text()}`);
  const { importId } = await response.json();
  await until(`import ${filename} to complete`, async () => {
    const list = await (await page.request.get("/api/imports")).json();
    return list.find(row => row.id === importId)?.status === "completed";
  }, 120_000);
  return importId;
}

export async function transactionsText(page) {
  const origin = new URL(page.url()).origin;
  await page.goto(`${origin}/money/transactions`);
  await page.waitForLoadState("networkidle").catch(() => {});
  return page.locator("main").innerText();
}

export const statement = (rows) => ["date,description,amount", ...rows.map(([date, description, amount]) => `${date},${description},${amount}`), ""].join("\n");

// End-to-end checks of the PACKAGED desktop app (after npm run desktop:dist), in temporary homes.
//   node scripts/desktop/package-smoke.mjs [path to the executable]
// Playwright drives the app over the Chrome DevTools protocol (--remote-debugging-port, which the
// packaged app accepts only with MONEO_DESKTOP_DEBUG=1): its --inspect fuse is off, which
// Playwright's _electron.launch needs. MONEO_DESKTOP_DEBUG=1 also enables the --debug-action hooks
// that stand in for tray clicks. Windows-only steps (window messages) are skipped elsewhere.
import { spawn } from "node:child_process";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { FuseState, FuseV1Options, getCurrentFuseWire } from "@electron/fuses";
import { alive, check, defaultExe, Desktop, importCsv, listeningPid, statement, summary, tempHome, transactionsText, until } from "./harness.mjs";

const exe = path.resolve(process.argv[2] ?? defaultExe());
if (!existsSync(exe)) { console.error(`No packaged app at ${exe}. Run npm run desktop:build && npm run desktop:dist first.`); process.exit(1); }
const windows = process.platform === "win32";

const fuses = await getCurrentFuseWire(exe);
const off = option => fuses[option] === FuseState.DISABLE, on = option => fuses[option] === FuseState.ENABLE;
check("fuses: RunAsNode, NODE_OPTIONS and --inspect off; cookie encryption, asar-only and asar integrity on",
  off(FuseV1Options.RunAsNode) && off(FuseV1Options.EnableNodeOptionsEnvironmentVariable) && off(FuseV1Options.EnableNodeCliInspectArguments)
  && on(FuseV1Options.EnableCookieEncryption) && on(FuseV1Options.OnlyLoadAppFromAsar) && (process.platform === "linux" || on(FuseV1Options.EnableEmbeddedAsarIntegrityValidation)));

// Without MONEO_DESKTOP_DEBUG the packaged app refuses debugging switches before doing anything.
for (const flag of ["--remote-debugging-port=0", "--inspect"]) {
  const home = tempHome("refuse");
  const env = { ...process.env, MONEO_DESKTOP_HOME: home };
  delete env.MONEO_DESKTOP_DEBUG;
  const child = spawn(exe, [flag], { env, stdio: "ignore" });
  const code = await Promise.race([new Promise(resolve => child.on("exit", resolve)), new Promise(resolve => setTimeout(() => resolve("running"), 15_000))]);
  if (code === "running") child.kill();
  const log = existsSync(path.join(home, "logs", "main.log")) ? readFileSync(path.join(home, "logs", "main.log"), "utf8") : "";
  check(`refuses ${flag.split("=")[0]} without MONEO_DESKTOP_DEBUG`, code === 1 && /Refusing to start/.test(log) && !existsSync(path.join(home, "config.json")), `exit ${code}`);
}

const app = new Desktop(exe, "smoke");
const backups = () => existsSync(path.join(app.home, "backups")) ? readdirSync(path.join(app.home, "backups")) : [];
const newBackup = async (before, reason) => until(`a ${reason} backup`, async () => backups().find(name => !before.includes(name) && name.includes(reason)), 60_000);

try {
  // First run, Home, navigation rules.
  await app.launch();
  const setup = await app.setupPage();
  check("setup window appears", true, await setup.locator("#title").innerText());
  let page = await app.appPage();
  await page.waitForLoadState("load");
  const port = Number(new URL(page.url()).port);
  const home = await page.locator("body").innerText();
  check("app window loads Home", new URL(page.url()).pathname === "/" && !/could not sign you in/i.test(home), page.url());
  check("setup window closes after start", !(await app.urls()).some(url => url.endsWith("/setup/index.html")));

  const external = "https://example.com/moneo-desktop-smoke";
  await page.evaluate(url => { window.location.assign(url); }, external);
  await until("the external link in the log", async () => app.external().includes(external), 10_000);
  check("external navigation goes to the system browser, not the window", new URL(page.url()).hostname === "localhost");
  const popup = "https://example.org/moneo-desktop-popup";
  await page.evaluate(url => { window.open(url, "_blank"); }, popup);
  await until("the popup in the log", async () => app.external().includes(popup), 10_000);
  check("window.open goes to the system browser", !(await app.urls()).some(url => url.includes("example.org")));

  // Microphone (voice calls): granted for Moneo's pages, denied for a frame of another origin.
  const mic = await page.evaluate(async () => {
    const ask = async scope => scope.navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => { stream.getTracks().forEach(track => track.stop()); return "granted"; }, error => error.name);
    const frame = document.createElement("iframe");
    frame.setAttribute("sandbox", "allow-scripts");
    frame.setAttribute("allow", "microphone *");
    frame.srcdoc = "<p>other origin</p>";
    document.body.append(frame);
    await new Promise(resolve => frame.addEventListener("load", resolve, { once: true }));
    const other = await new Promise(resolve => {
      window.addEventListener("message", event => resolve(event.data), { once: true });
      const script = frame.contentDocument ? null : true; void script;
      frame.contentWindow.postMessage("ask", "*");
    }).catch(() => "unreachable");
    frame.remove();
    return { app: await ask(window), other };
  }).catch(error => ({ error: error.message }));
  check("microphone is granted for Moneo's own page", mic.app === "granted", JSON.stringify(mic));

  // Tray: Back up now, Open in browser (the hooks call the tray menu's own actions).
  let before = backups();
  await app.second(["--debug-action=backUp"]);
  check("tray Back up now writes a backup", await newBackup(before, "manual").catch(() => false));
  await app.second(["--debug-action=openInBrowser"]);
  await until("Open in browser in the log", async () => app.external().includes(`http://localhost:${port}/`), 10_000).catch(() => {});
  check("tray Open in browser goes to the system browser", app.external().includes(`http://localhost:${port}/`));

  // Close hides to the tray; a second launch brings the window back.
  if (windows) {
    const handle = app.mainWindow();
    app.closeWindow(handle);
    await until("the window to hide", async () => !app.windowVisible(handle), 10_000);
    const health = await fetch(`http://127.0.0.1:${port}/api/health`, { headers: { authorization: "Bearer smoke" } });
    check("closing the window hides it and the server keeps answering", !app.child.exited && health.ok, `health ${health.status}`);
    await app.second([]);
    check("launching Moneo again shows the hidden window", await until("the window to show", async () => app.windowVisible(handle), 10_000).catch(() => false));
  }

  // Crash: the server is restarted.
  const serverPid = listeningPid(port);
  process.kill(serverPid);
  await until("the server to go down", async () => !alive(serverPid), 10_000);
  const restartedPid = await until("the server to come back", async () => {
    const response = await fetch(`http://127.0.0.1:${port}/api/health`, { headers: { authorization: "Bearer smoke" } });
    return response.ok && listeningPid(port);
  }, 90_000).catch(() => null);
  await page.reload();
  check("a crashed server is restarted", restartedPid && restartedPid !== serverPid && /Restarting the Next server/.test(app.log()), `pid ${serverPid} → ${restartedPid}`);

  // Restore: data from before the backup comes back, data written after it is gone.
  await importCsv(page, { filename: "before-backup.csv", accountName: "Smoke checking", csv: statement([["2026-09-01", "Before backup coffee", "-3.20"]]) });
  before = backups();
  await app.second(["--debug-action=backUp"]);
  const folder = path.join(app.home, "backups", await newBackup(before, "manual"));
  await importCsv(page, { filename: "after-backup.csv", accountName: "Smoke checking", csv: statement([["2026-09-02", "After backup tea", "-2.10"]]) });
  const beforeRestore = backups();
  await app.second([`--debug-action=restore=${folder}`]);
  await until("the restore", async () => app.log().includes(`Restored from ${folder}`), 180_000);
  page = await app.appPage();
  await until("Home after the restore", async () => (await fetch(`http://127.0.0.1:${port}/api/health`)).ok, 120_000);
  const restored = await transactionsText(page);
  check("restore brings back data from before the backup and drops later data", restored.includes("Before backup coffee") && !restored.includes("After backup tea"));
  check("restore keeps a backup of the replaced data", backups().some(name => !beforeRestore.includes(name) && name.includes("before-restore")));

  // Quit, then start again in the same home: the data is kept.
  app.snapshot();
  await app.quit();
  const left = [...app.seen.values()].filter(row => alive(row.pid));
  check("quit stops every process", left.length === 0, left.map(row => `${row.name}#${row.pid}`).join(", "));
  check("the server port is closed after quit", !(await fetch(`http://127.0.0.1:${port}/api/health`).then(() => true, () => false)));
  await app.launch();
  page = await app.appPage(120_000);
  const relaunched = await transactionsText(page);
  check("relaunching in the same home keeps the data", relaunched.includes("Before backup coffee"));
  check("the app keeps its port", Number(new URL(page.url()).port) === port);

  // A database that cannot start: the error screen, then Retry.
  app.snapshot();
  await app.quit();
  const version = path.join(app.home, "postgres", "PG_VERSION");
  const original = readFileSync(version, "utf8");
  writeFileSync(version, "99\n");
  await app.launch();
  const failed = await app.setupPage();
  await until("the error screen", async () => !(await failed.locator("#failure").isHidden()), 120_000);
  check("a database that cannot start shows the error screen", /could not start/i.test(await failed.locator("#title").innerText()), (await failed.locator("#error-summary").innerText()).slice(0, 160));
  const setupMic = await failed.evaluate(() => navigator.mediaDevices.getUserMedia({ audio: true }).then(() => "granted", error => error.name));
  check("microphone is denied outside Moneo's pages (the local status window)", setupMic !== "granted", setupMic);
  writeFileSync(version, original);
  await failed.locator("#retry").click();
  page = await app.appPage(180_000);
  check("Retry starts Moneo once the problem is fixed", (await transactionsText(page)).includes("Before backup coffee"));

  app.snapshot();
  await app.quit();
  const leftAll = [...app.seen.values()].filter(row => alive(row.pid));
  check("no process from any launch is left", leftAll.length === 0, leftAll.map(row => `${row.name}#${row.pid}`).join(", "));
} catch (error) {
  check("smoke run", false, error.message);
} finally {
  await app.cleanup();
}

process.exit(summary() ? 1 : 0);

// End-to-end checks of the PACKAGED desktop app (after npm run desktop:dist), in temporary homes.
//   node scripts/desktop/package-smoke.mjs [path to the executable]
// Playwright drives the app over the Chrome DevTools protocol (--remote-debugging-port, which the
// packaged app accepts only with MONEO_DESKTOP_DEBUG=1): its --inspect fuse is off, which
// Playwright's _electron.launch needs. MONEO_DESKTOP_DEBUG=1 also enables the --debug-action hooks
// that stand in for tray clicks. Window-message steps run on Windows only.
import { spawn } from "node:child_process";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { FuseState, FuseV1Options, getCurrentFuseWire } from "@electron/fuses";
import { alive, check, defaultExe, Desktop, importCsv, listeningPid, statement, summary, tempHome, transactionsText, until } from "./harness.mjs";

const exe = path.resolve(process.argv[2] ?? defaultExe());
if (!existsSync(exe)) { console.error(`No packaged app at ${exe}. Run npm run desktop:build && npm run desktop:dist first.`); process.exit(1); }
const windows = process.platform === "win32";

const fuses = await getCurrentFuseWire(exe);
const off = option => fuses[option] === FuseState.DISABLE, on = option => fuses[option] === FuseState.ENABLE;
check("fuses: RunAsNode, NODE_OPTIONS and --inspect off; cookie encryption, asar-only and asar integrity on",
  off(FuseV1Options.RunAsNode) && off(FuseV1Options.EnableNodeOptionsEnvironmentVariable) && off(FuseV1Options.EnableNodeCliInspectArguments)
  && on(FuseV1Options.EnableCookieEncryption) && on(FuseV1Options.OnlyLoadAppFromAsar) && (process.platform === "linux" || on(FuseV1Options.EnableEmbeddedAsarIntegrityValidation)));

// Without MONEO_DESKTOP_DEBUG the packaged app refuses debugging switches before doing anything.
for (const flag of ["--remote-debugging-port=0", "--remote-debugging-pipe", "--inspect"]) {
  const home = tempHome("refuse");
  const env = { ...process.env, MONEO_DESKTOP_HOME: home };
  delete env.MONEO_DESKTOP_DEBUG;
  const child = spawn(exe, [flag], { env, stdio: "ignore" });
  const code = await Promise.race([new Promise(resolve => child.on("exit", resolve)), new Promise(resolve => setTimeout(() => resolve("running"), 15_000))]);
  if (code === "running") child.kill();
  const log = existsSync(path.join(home, "logs", "main.log")) ? readFileSync(path.join(home, "logs", "main.log"), "utf8") : "";
  check(`refuses ${flag.split("=")[0]} without MONEO_DESKTOP_DEBUG`, code === 1 && /Refusing to start/.test(log) && !existsSync(path.join(home, "config.json")), `exit ${code}`);
}

const app = new Desktop(exe, "smoke");
const backups = () => existsSync(path.join(app.home, "backups")) ? readdirSync(path.join(app.home, "backups")) : [];
const newBackup = (before, reason) => until(`a ${reason} backup`, async () => backups().find(name => !before.includes(name) && name.includes(reason)), 60_000);
const health = port => fetch(`http://127.0.0.1:${port}/api/health`, { headers: { authorization: "Bearer smoke" } }).then(response => response.ok, () => false);

try {
  // First run, Home, navigation rules.
  await app.launch();
  const setup = await app.setupPage();
  check("setup window appears", true, await setup.locator("#title").innerText());
  let page = await app.appPage();
  await page.waitForLoadState("load");
  const port = Number(new URL(page.url()).port);
  check("app window loads Home", new URL(page.url()).pathname === "/" && !/could not sign you in/i.test(await page.locator("body").innerText()), page.url());
  check("setup window closes after start", !(await app.urls()).some(url => url.endsWith("/setup/index.html")));

  const external = "https://example.com/moneo-desktop-smoke";
  await page.evaluate(url => { window.location.assign(url); }, external);
  await until("the external link in the log", async () => app.external().includes(external), 10_000);
  check("external navigation goes to the system browser, not the window", new URL(page.url()).hostname === "localhost");
  const popup = "https://example.org/moneo-desktop-popup";
  await page.evaluate(url => { window.open(url, "_blank"); }, popup);
  await until("the popup in the log", async () => app.external().includes(popup), 10_000);
  check("window.open goes to the system browser", !(await app.urls()).some(url => url.includes("example.org")));

  // Voice calls: the microphone is granted for Moneo's page (a fake device stands in for a real one).
  const mic = await page.evaluate(() => navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => { stream.getTracks().forEach(track => track.stop()); return "granted"; }, error => error.name));
  check("microphone is granted for Moneo's own page", mic === "granted", mic);

  // Tray: Back up now, Open in browser (the hooks call the tray menu's own actions).
  let before = backups();
  await app.second(["--debug-action=backUp"]);
  check("tray Back up now writes a backup", await newBackup(before, "manual").catch(() => false));
  await app.second(["--debug-action=openInBrowser"]);
  await until("Open in browser in the log", async () => app.external().includes(`http://localhost:${port}/`), 10_000).catch(() => {});
  check("tray Open in browser goes to the system browser", app.external().includes(`http://localhost:${port}/`));

  // Close hides to the tray; a second launch brings the window back.
  if (windows) {
    const handle = app.mainWindow();
    app.closeWindow(handle);
    await until("the window to hide", async () => !app.windowVisible(handle), 10_000);
    check("closing the window hides it and the server keeps answering", !app.child.exited && await health(port));
    await app.second([]);
    check("launching Moneo again shows the hidden window", await until("the window to show", async () => app.windowVisible(handle), 10_000).catch(() => false));
  }

  // Crash: the server is restarted.
  const serverPid = listeningPid(port);
  process.kill(serverPid);
  await until("the server to go down", async () => !alive(serverPid), 10_000);
  const restartedPid = await until("the server to come back", async () => await health(port) && listeningPid(port), 90_000).catch(() => null);
  await page.reload();
  check("a crashed server is restarted", restartedPid && restartedPid !== serverPid && /Restarting the Next server/.test(app.log()), `pid ${serverPid} → ${restartedPid}`);

  // Restore: data from before the backup comes back, data written after it is gone.
  await importCsv(page, { filename: "before-backup.csv", accountName: "Smoke checking", csv: statement([["2026-09-01", "Before backup coffee", "-3.20"]]) });
  before = backups();
  await app.second(["--debug-action=backUp"]);
  const folder = path.join(app.home, "backups", await newBackup(before, "manual"));
  await importCsv(page, { filename: "after-backup.csv", accountName: "Smoke checking", csv: statement([["2026-09-02", "After backup tea", "-2.10"]]) });
  const beforeRestore = backups();
  await app.second([`--debug-action=restore=${folder}`]);
  await until("the restore", async () => app.log().includes(`Restored from ${folder}`), 180_000);
  page = await app.appPage();
  await until("the server after the restore", async () => health(port), 120_000);
  const restored = await transactionsText(page);
  check("restore brings back data from before the backup and drops later data", restored.includes("Before backup coffee") && !restored.includes("After backup tea"));
  check("restore keeps a backup of the replaced data", backups().some(name => !beforeRestore.includes(name) && name.includes("before-restore")));

  // Quit, then start again in the same home: the data is kept.
  app.snapshot();
  await app.quit();
  const left = [...app.seen.values()].filter(row => alive(row.pid));
  check("quit stops every process", left.length === 0, left.map(row => `${row.name}#${row.pid}`).join(", "));
  check("the server port is closed after quit", !(await health(port)));
  await app.launch();
  page = await app.appPage(120_000);
  check("relaunching in the same home keeps the data", (await transactionsText(page)).includes("Before backup coffee"));
  check("the app keeps its port", Number(new URL(page.url()).port) === port);

  // A database that cannot start: the error screen, then Retry.
  app.snapshot();
  await app.quit();
  const versionFile = path.join(app.home, "postgres", "PG_VERSION");
  const original = readFileSync(versionFile, "utf8");
  writeFileSync(versionFile, "99\n");
  await app.launch();
  const failed = await app.setupPage();
  await until("the error screen", async () => !(await failed.locator("#failure").isHidden()), 120_000);
  check("a database that cannot start shows the error screen", /could not start/i.test(await failed.locator("#title").innerText()), (await failed.locator("#error-summary").innerText()).slice(0, 160));
  const setupMic = await failed.evaluate(() => navigator.mediaDevices.getUserMedia({ audio: true }).then(() => "granted", error => error.name));
  check("microphone is denied outside Moneo's pages (the local status window)", setupMic === "NotAllowedError", setupMic);
  writeFileSync(versionFile, original);
  await failed.locator("#retry").click();
  page = await app.appPage(180_000);
  check("Retry starts Moneo once the problem is fixed", (await transactionsText(page)).includes("Before backup coffee"));

  app.snapshot();
  await app.quit();
  const leftAll = [...app.seen.values()].filter(row => alive(row.pid));
  check("no process from any launch is left", leftAll.length === 0, leftAll.map(row => `${row.name}#${row.pid}`).join(", "));
} catch (error) {
  check("smoke run", false, error.message);
} finally {
  await app.cleanup();
}

process.exit(summary() ? 1 : 0);

